/**
 * `entity/ThrownItemEntity.java`: the one projectile entity of every ejected throwable (ADR
 * 0056 D7), mirroring the runtime's `MsmThrownItem` (Minecraft 26.3, Mojang names) and
 * registered as `<mod id>:<path>` (normally `thrown_item`) with the snowball's entity type
 * settings. Written only when the project has a throwable.
 *
 * @packageDocumentation
 */

import { javaString } from '../java';

/**
 * The source of `<package>/entity/ThrownItemEntity.java`.
 *
 * @param javaPackage - The mod's Java package.
 * @param modId - The mod id, the namespace of the entity type.
 * @param path - The path of the entity type id (`thrown_item` unless a project entity has it).
 */
export function thrownItemEntityJava(javaPackage: string, modId: string, path: string): string {
  return `// Generated by MCSuperMods: the thrown item entity as the runtime's MsmThrownItem.
package ${javaPackage}.entity;

import ${javaPackage}.item.ThrowableItem;
import java.util.Optional;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Registry;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.core.registries.Registries;
import net.minecraft.resources.Identifier;
import net.minecraft.resources.ResourceKey;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.MobCategory;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.entity.projectile.throwableitemprojectile.ThrowableItemProjectile;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.Items;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import net.minecraft.world.phys.BlockHitResult;
import net.minecraft.world.phys.EntityHitResult;
import net.minecraft.world.phys.HitResult;

/**
 * A thrown {@link ThrowableItem}. It carries a copy of the thrown item (drawn by vanilla's {@code ThrownItemRenderer})
 * and reads its behaviour from that item's settings: gravity, {@code damage} and {@code on_hit_entity} on an entity
 * hit, {@code on_hit_block} on a block hit, then {@code after_throw} ({@code DROP}: the item drops where it lands;
 * {@code RETURN}: back into the thrower's inventory, or at their feet when it is full, where it lands when there is no
 * thrower) and the entity is discarded.
 */
public class ThrownItemEntity extends ThrowableItemProjectile {
    private static final String CARRIES_ITEM = "msm_carries_item";

    /** {@code ${modId}:${path}}: the snowball's settings (0.25 by 0.25, no loot table, tracking range 4, update interval 10). */
    public static final ResourceKey<EntityType<?>> KEY = ResourceKey.create(Registries.ENTITY_TYPE,
            Identifier.fromNamespaceAndPath(${javaString(modId)}, ${javaString(path)}));
    public static final EntityType<ThrownItemEntity> TYPE = Registry.register(BuiltInRegistries.ENTITY_TYPE, KEY,
            EntityType.Builder.<ThrownItemEntity>of(ThrownItemEntity::new, MobCategory.MISC)
                    .noLootTable()
                    .sized(0.25f, 0.25f)
                    .clientTrackingRange(4)
                    .updateInterval(10)
                    .build(KEY));

    /** Whether the item comes back ({@code DROP}, {@code RETURN}); false for creative throws and broken copies. */
    private boolean carriesItem;

    public ThrownItemEntity(EntityType<? extends ThrownItemEntity> type, Level level) {
        super(type, level);
    }

    public ThrownItemEntity(Level level, LivingEntity owner, ItemStack stack) {
        super(TYPE, owner, level, stack);
    }

    public ThrownItemEntity(Level level, double x, double y, double z, ItemStack stack) {
        super(TYPE, x, y, z, level, stack);
    }

    /** Loads the class, registering the entity type. */
    public static void register() {}

    public void setCarriesItem(boolean carriesItem) {
        this.carriesItem = carriesItem;
    }

    public boolean carriesItem() {
        return carriesItem;
    }

    /** Shown when the entity has no item (never for a throw by this mod). */
    @Override
    protected Item getDefaultItem() {
        return Items.SNOWBALL;
    }

    /** The carried item, if it is a throwable. */
    private Optional<ThrowableItem> throwable() {
        return getItem().getItem() instanceof ThrowableItem item ? Optional.of(item) : Optional.empty();
    }

    @Override
    protected double getDefaultGravity() {
        return throwable().map(t -> (double) t.settings().gravity()).orElse(super.getDefaultGravity());
    }

    @Override
    protected void onHitEntity(EntityHitResult result) {
        super.onHitEntity(result);
        if (!(level() instanceof ServerLevel level)) {
            return;
        }
        Optional<ThrowableItem> throwable = throwable();
        Entity target = result.getEntity();
        if (throwable.isPresent() && throwable.get().settings().damage() > 0) {
            target.hurtServer(level, damageSources().thrown(this, getOwner()), throwable.get().settings().damage());
        }
        LivingEntity living = target instanceof LivingEntity l ? l : null;
        throwable.ifPresent(item -> item.onHitEntity(level, result.getLocation(), target.blockPosition().immutable(), getOwner(), living));
    }

    @Override
    protected void onHitBlock(BlockHitResult result) {
        super.onHitBlock(result);
        if (!(level() instanceof ServerLevel level)) {
            return;
        }
        BlockPos pos = result.getBlockPos().immutable();
        throwable().ifPresent(item -> item.onHitBlock(level, result.getLocation(), pos, getOwner()));
    }

    /** The hit (entity or block, through {@code super}), then {@code after_throw}; the entity is discarded. */
    @Override
    protected void onHit(HitResult result) {
        super.onHit(result);
        if (level() instanceof ServerLevel level && !isRemoved()) {
            if (carriesItem) {
                land(level);
            }
            discard();
        }
    }

    private void land(ServerLevel level) {
        ItemStack stack = getItem().copy();
        if (stack.isEmpty()) {
            return;
        }
        ThrowableItem.AfterThrow mode = throwable().map(t -> t.settings().afterThrow()).orElse(ThrowableItem.AfterThrow.DROP);
        if (mode == ThrowableItem.AfterThrow.RETURN && getOwner() instanceof Player player && player.isAlive()) {
            player.getInventory().add(stack); // takes what fits from the stack
            if (!stack.isEmpty() && player.level() instanceof ServerLevel playerLevel) {
                player.spawnAtLocation(playerLevel, stack);
            }
            return;
        }
        if (mode == ThrowableItem.AfterThrow.DROP || mode == ThrowableItem.AfterThrow.RETURN) {
            spawnAtLocation(level, stack);
        }
    }

    @Override
    protected void addAdditionalSaveData(ValueOutput output) {
        super.addAdditionalSaveData(output);
        output.putBoolean(CARRIES_ITEM, carriesItem);
    }

    @Override
    protected void readAdditionalSaveData(ValueInput input) {
        super.readAdditionalSaveData(input);
        carriesItem = input.getBooleanOr(CARRIES_ITEM, false);
    }
}
`;
}
